            C++

    #include <iostream>
#include <vector>
using namespace std ;

// Merge two halves in a stable way
void merge(vector<string>& arr, int left, int mid, int right) {
    int n1 = mid - left + 1 ;
    int n2 = right - mid ;

    vector<string> L(n1), R(n2) ;

    // Copy data to temporary arrays
    for (int i = 0; i < n1; i++)
        L[i] = arr[left + i];
    for (int j = 0; j < n2; j++)
        R[j] = arr[mid + 1 + j];

    int i = 0, j = 0, k = left;

    // Merge the two halves in a stable way (by length)
    while (i < n1 && j < n2) {
        if (L[i].length() <= R[j].length()) {
            arr[k++] = L[i++] ;
        } else {
            arr[k++] = R[j++] ;
        }
    }

    // Copy remaining elements of L[]
    while (i < n1) {
        arr[k++] = L[i++] ;
    }

    // Copy remaining elements of R[]
    while (j < n2) {
        arr[k++] = R[j++] ;
    }
}

// Merge Sort (recursive)
void mergeSort(vector<string>& arr, int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;

        mergeSort(arr, left, mid) ;
        mergeSort(arr, mid + 1, right) ;

        merge(arr, left, mid, right) ;
    }
}

// Function to sort strings based on their length
void sortByLength(vector<string>& arr) {
    mergeSort(arr, 0, arr.size() - 1) ;
}

int main() {
    vector<string> arr = {"GeeksforGeeks", "I", "from", "am"} ;

    sortByLength(arr) ; 

    for (auto& s : arr)
        cout << s << " " ;

    return 0 ;
}


